  1 | import { useEffect, useCallback, useRef } from "react";
  2 | import { usePlayer } from "./usePlayer";
  3 | import { useAudioEngine } from "./useAudioEngine";
  4 | import type { Track } from "../types";
  5 | 
  6 | export function usePlayerWithAudio(initialPlaylist: Track[] = []) {
  7 |   const player = usePlayer(initialPlaylist);
  8 |   const isSeekingRef = useRef(false);
  9 | 
 10 |   const handleTimeUpdate = useCallback(
 11 |     (time: number) => {
 12 |       if (!isSeekingRef.current) {
 13 |         player.setCurrentTime(time);
 14 |       }
 15 |     },
 16 |     [player]
 17 |   );
 18 | 
 19 |   const handleDurationChange = useCallback(
 20 |     (duration: number) => {
 21 |       if (isFinite(duration) && duration > 0) {
 22 |         player.setDuration(duration);
 23 |       }
 24 |     },
 25 |     [player]
 26 |   );
 27 | 
 28 |   const handleEnded = useCallback(() => {
 29 |     const { repeatMode, playlist, currentTrack } = player.state;
 30 |     if (repeatMode === "one" && currentTrack) {
 31 |       // Repeat one: replay the same track
 32 |       player.play(currentTrack);
 33 |     } else if (repeatMode === "all" && playlist.length > 0) {
 34 |       player.next();
 35 |     } else {
 36 |       // "none" or end of playlist: stop
 37 |       const currentIndex = playlist.findIndex(
 38 |         (t) => t.id === currentTrack?.id
 39 |       );
 40 |       if (currentIndex < playlist.length - 1) {
 41 |         player.next();
 42 |       } else {
 43 |         player.pause();
 44 |         player.seek(0);
 45 |       }
 46 |     }
 47 |   }, [player]);
 48 | 
 49 |   const handleError = useCallback(
 50 |     (error: string) => {
 51 |       console.error("[Llama Player]", error);
 52 |     },
 53 |     []
 54 |   );
 55 | 
 56 |   const handleLoadStart = useCallback(() => {
 57 |     // Could set a loading state here
 58 |   }, []);
 59 | 
 60 |   const handleCanPlay = useCallback(() => {
 61 |     // Audio is ready to play
 62 |   }, []);
 63 | 
 64 |   const audio = useAudioEngine({
 65 |     onTimeUpdate: handleTimeUpdate,
 66 |     onDurationChange: handleDurationChange,
 67 |     onEnded: handleEnded,
 68 |     onError: handleError,
 69 |     onLoadStart: handleLoadStart,
 70 |     onCanPlay: handleCanPlay,
 71 |   });
 72 | 
 73 |   // When currentTrack changes, load it in the audio engine
 74 |   useEffect(() => {
 75 |     if (player.state.currentTrack) {
 76 |       audio.loadTrack(player.state.currentTrack);
 77 |     }
 78 |   }, [player.state.currentTrack?.id]); // eslint-disable-line react-hooks/exhaustive-deps
 79 | 
 80 |   // Sync play/pause with audio engine
 81 |   useEffect(() => {
 82 |     if (player.state.isPlaying) {
 83 |       audio.play();
 84 |     } else {
 85 |       audio.pause();
 86 |     }
 87 |   }, [player.state.isPlaying]); // eslint-disable-line react-hooks/exhaustive-deps
 88 | 
 89 |   // Sync volume with audio engine
 90 |   useEffect(() => {
 91 |     audio.setVolume(player.state.volume);
 92 |   }, [player.state.volume]); // eslint-disable-line react-hooks/exhaustive-deps
 93 | 
 94 |   // Override seek to also seek in audio engine
 95 |   const seek = useCallback(
 96 |     (time: number) => {
 97 |       isSeekingRef.current = true;
 98 |       player.seek(time);
 99 |       audio.seek(time);
100 |       // Small timeout to allow audio to process the seek
101 |       setTimeout(() => {
102 |         isSeekingRef.current = false;
103 |       }, 50);
104 |     },
105 |     [player, audio]
106 |   );
107 | 
108 |   // Override play to ensure track is loaded
109 |   const play = useCallback(
110 |     (track?: Track) => {
111 |       if (track) {
112 |         audio.loadTrack(track);
113 |       }
114 |       player.play(track);
115 |     },
116 |     [player, audio]
117 |   );
118 | 
119 |   // Override stop
120 |   const stop = useCallback(() => {
121 |     player.stop();
122 |     audio.stop();
123 |   }, [player, audio]);
124 | 
125 |   return {
126 |     state: player.state,
127 |     play,
128 |     pause: player.pause,
129 |     stop,
130 |     next: player.next,
131 |     prev: player.prev,
132 |     seek,
133 |     setVolume: player.setVolume,
134 |     loadPlaylist: player.loadPlaylist,
135 |     addTrack: player.addTrack,
136 |     removeTrack: player.removeTrack,
137 |     reorderPlaylist: player.reorderPlaylist,
138 |     setRepeatMode: player.setRepeatMode,
139 |     toggleShuffle: player.toggleShuffle,
140 |   };
141 | }
